                {p.tieneAgua && <div className="fbcrm-form fbcrm-sep"><Campo label="Detalle de los derechos de agua" ancho><input value={p.aguaDetalle} onChange={(e) => setPredio(i, 'aguaDetalle', e.target.value)} placeholder="Ej. 31 l/s del canal Cocalán, 1,5 acciones" /></Campo></div>}
